package io.github.luckolite.interpreter;
import java.util.*;import java.io.*;import org.junit.Test;import static org.junit.Assert.*;
public final class AndroidLocalManagedCaptureOriginalTest {
 record Scene(byte[] labels,byte[] gray,List<MeasureRegion>measures){}
 static Scene scene(){int w=600,h=240;byte[] l=new byte[w*h],g=new byte[w*h];Arrays.fill(g,(byte)255);for(int line=0;line<5;line++)for(int x=20;x<580;x++){l[(80+line*16)*w+x]=4;g[(80+line*16)*w+x]=(byte)120;}for(int cx:new int[]{180,360}){int cy=cx==180?128:112;for(int y=cy-7;y<=cy+7;y++)for(int x=cx-11;x<=cx+11;x++)if((x-cx)*(x-cx)/100.0+(y-cy)*(y-cy)/36.0<=1){l[y*w+x]=2;g[y*w+x]=0;}for(int y=cy-52;y<=cy;y++)for(int x=cx+9;x<=cx+10;x++){l[y*w+x]=5;g[y*w+x]=0;}}return new Scene(l,g,List.of(new MeasureRegion(.03f,.97f,.2f,.8f)));}
 static ScoreClockContextSource capture(Scene scene,AndroidAnalysisSelectionProbe.Selected selected){var a=selected.score();assertFalse("genuine normal source must emit notes",a.notes().isEmpty());var page=new ScorePageInterpretation(scene.measures(),a.notes(),0,a.keyChanges(),List.of(),List.of(),a.rests(),List.of(),List.of()).withTremoloSource(a.tremoloSource());return ScoreClockContextCapture.capture(scene.labels(),scene.gray(),600,240,page,selected.clockAnalysis(),null,null);}
 static void assertFacts(ScoreClockContextSource context,int notes){assertEquals(notes,context.noteCount());assertEquals(notes,context.printedValues().size());assertFalse("genuine labelled-glyph facts must survive",context.glyphLedgers().isEmpty());assertTrue(context.glyphLedgers().get(0).population()>0);assertFalse(context.missing().isEmpty());}
 @Test public void localFallbackSnapshotComesFromActualNormalProducer(){var s=scene();var selected=AndroidAnalysisSelectionProbe.select(null,s.labels(),s.gray(),600,240,s.measures());assertNotNull("local fallback must be captured after selection",selected.clockAnalysis());assertSame(selected.score(),selected.clockAnalysis());assertFalse(selected.clockAnalysis().clockProducerSource().emissions().isEmpty());assertFacts(capture(s,selected),selected.score().notes().size());}
 @Test public void managedSelectionKeepsCompactGenuineProducerContext()throws Exception{var s=scene();var genuine=OmrScoreInterpreter.analyze(s.labels(),s.gray(),600,240,s.measures());assertFalse(genuine.clockProducerSource().emissions().isEmpty());var b=new ByteArrayOutputStream();NativeDecoderWire.writeAnalysis(new DataOutputStream(b),genuine);var remote=NativeDecoderWire.readAnalysis(new DataInputStream(new ByteArrayInputStream(b.toByteArray())),s.measures().size());assertTrue(remote.clockProducerSource().emissions().isEmpty());assertFalse(remote.clockContextSource().printedValues().isEmpty());var selected=AndroidAnalysisSelectionProbe.select(remote,s.labels(),s.gray(),600,240,s.measures());assertSame(remote,selected.score());assertSame(remote,selected.clockAnalysis());assertFacts(capture(s,selected),remote.notes().size());}
}
